// Keep ownership across registration, including its error/unwind paths.
// Generic only to exercise the same RAII policy without creating OS handles.
fn register_event_handle<T>(
    event: T,
    register: impl FnOnce(&T) -> WasapiRes<()>,
) -> WasapiRes<T> {
    register(&event)?;
    Ok(event)
}

fn event_wait_result(
    result: WAIT_EVENT,
    failure_error: impl FnOnce() -> windows_core::Error,
) -> WasapiRes<()> {
    match result {
        WAIT_OBJECT_0 => Ok(()),
        WAIT_TIMEOUT => Err(WasapiError::EventTimeout),
        WAIT_FAILED => Err(failure_error().into()),
        unexpected => Err(WasapiError::UnexpectedWaitResult(unexpected.0)),
    }
}

